         WHERE EXISTS (
           SELECT 1
           FROM review_runs
           WHERE id = ? AND status = 'running' AND attempt_count = ?
         )`
      )
      .bind(
        findingId,
        input.reviewId,
        finding.severity,
        finding.category,
        finding.passType,
        finding.description,
        JSON.stringify(finding.locations),
        finding.suggestedFix,
        input.reviewId,
        input.expectedAttemptCount
      )
      .run();
  }
}

